import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import * as fs from 'fs';
import * as path from 'path';
import { makeServices, makeTempDir, SAMPLES_DIR } from './helpers';

describe('IndexingService', () => {
  let dir: string;
  beforeEach(() => {
    dir = makeTempDir();
    vi.spyOn(console, 'log').mockImplementation(() => {});
  });
  afterEach(() => fs.rmSync(dir, { recursive: true, force: true }));

  it('indexing a single document makes its chunks retrievable and marks it indexed', async () => {
    const s = makeServices(dir);
    const doc = s.documentService.importDocument(path.join(SAMPLES_DIR, 'design-notes.md'));
    const status = await s.indexingService.startIndexing(doc.id);

    expect(s.indexingService.getAllChunks().length).toBeGreaterThan(0);
    expect(s.documentService.getDocument(doc.id)?.status).toBe('indexed');
    expect(status).toMatchObject({ indexStatus: 'ready', documentsLoaded: 1, indexedCount: 1 });
  });

  it('batch indexing indexes every document', async () => {
    const s = makeServices(dir);
    for (const f of fs.readdirSync(SAMPLES_DIR)) s.documentService.importDocument(path.join(SAMPLES_DIR, f));
    const status = await s.indexingService.startIndexing();
    expect(status.indexedCount).toBe(3);
    expect(s.documentService.listDocuments().every(d => d.status === 'indexed')).toBe(true);
  });
});
EOF
