import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import * as fs from 'fs';
import * as path from 'path';
import { makeServices, makeTempDir, SAMPLES_DIR } from './helpers';

describe('answer feedback (QaService)', () => {
  let dir: string;
  beforeEach(() => {
    dir = makeTempDir();
    vi.spyOn(console, 'log').mockImplementation(() => {});
    vi.spyOn(console, 'warn').mockImplementation(() => {});
    vi.spyOn(Math, 'random').mockReturnValue(0); // shortest simulated delay
  });
  afterEach(() => {
    vi.restoreAllMocks();
    fs.rmSync(dir, { recursive: true, force: true });
  });

  it('every answer has a unique string id that is also stored in history', async () => {
    const { qaService } = makeServices(dir);
    const a = await qaService.ask('What is the architecture?');
    const b = await qaService.ask('What is the architecture?');
    expect(typeof a.id).toBe('string');
    expect(a.id.length).toBeGreaterThan(0);
    expect(a.id).not.toBe(b.id);
    expect(qaService.getHistory().map(h => h.response.id)).toEqual([a.id, b.id]);
  });

  it('submit stores a rating and list returns {answerId, rating, timestamp}', async () => {
    const { qaService } = makeServices(dir);
    const a = await qaService.ask('How does indexing work?');
    const before = Date.now();
    qaService.submitFeedback(a.id, 'up');

    const list = qaService.getFeedback();
    expect(list).toHaveLength(1);
    expect(Object.keys(list[0]).sort()).toEqual(['answerId', 'rating', 'timestamp']);
    expect(list[0]).toMatchObject({ answerId: a.id, rating: 'up' });
    expect(Date.parse(list[0].timestamp)).toBeGreaterThanOrEqual(before - 1000);
  });

  it('ratings persist across a restart (new service graph on the same data dir)', async () => {
    const first = makeServices(dir);
    first.documentService.importDocument(path.join(SAMPLES_DIR, 'design-notes.md'));
    await first.indexingService.startIndexing();
    const a = await first.qaService.ask('What design patterns are used?');
    const b = await first.qaService.ask('Tell me about retrieval');
    first.qaService.submitFeedback(a.id, 'up');
    first.qaService.submitFeedback(b.id, 'down');

    const second = makeServices(dir);
    expect(second.qaService.getFeedback().map(f => [f.answerId, f.rating])).toEqual([
      [a.id, 'up'],
      [b.id, 'down'],
    ]);
  });

  it('rating the same answer again replaces the previous rating', async () => {
    const { qaService } = makeServices(dir);
    const a = await qaService.ask('anything');
    qaService.submitFeedback(a.id, 'up');
    qaService.submitFeedback(a.id, 'down');
    expect(qaService.getFeedback()).toEqual([expect.objectContaining({ answerId: a.id, rating: 'down' })]);
  });

  it('rejects invalid ratings and unknown answer ids without storing anything', async () => {
    const { qaService } = makeServices(dir);
    const a = await qaService.ask('anything');
    expect(() => qaService.submitFeedback(a.id, 'meh' as never)).toThrow(/'up' or 'down'/);
    expect(() => qaService.submitFeedback('no-such-answer', 'up')).toThrow(/Unknown answer id/);
    expect(() => qaService.submitFeedback('', 'up')).toThrow(/non-empty/);
    expect(qaService.getFeedback()).toEqual([]);
  });

  it('assigns persistent ids to history entries saved before answers had ids', () => {
    const { persistence, qaService } = makeServices(dir);
    persistence.writeJson('qa-history.json', [
      { question: 'old', response: { answer: 'x', citations: [], confidence: 0.3, timestamp: '2026-01-01T00:00:00Z' } },
    ]);
    const id = qaService.getHistory()[0].response.id;
    expect(id).toEqual(expect.any(String));
    expect(makeServices(dir).qaService.getHistory()[0].response.id).toBe(id);
    expect(() => qaService.submitFeedback(id, 'up')).not.toThrow();
  });
});
