import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import * as fs from 'fs';
import { IPC_CHANNELS } from '../src/shared/types';
import { registerIpcHandlers } from '../src/main/ipc-handlers';
import { makeServices, makeTempDir } from './helpers';

// Capture what the preload exposes and which channels it invokes.
const exposed: Record<string, any> = {};
const invoke = vi.fn();
vi.mock('electron', () => ({
  contextBridge: { exposeInMainWorld: (key: string, api: unknown) => { exposed[key] = api; } },
  ipcRenderer: { invoke: (...args: unknown[]) => invoke(...args) },
  webUtils: { getPathForFile: () => '' },
}));

/** Fake ipcMain that records handlers so they can be called like the renderer would. */
function fakeIpcMain() {
  const handlers = new Map<string, (...args: any[]) => any>();
  return {
    handlers,
    handle: (channel: string, fn: (...args: any[]) => any) => handlers.set(channel, fn),
    call: (channel: string, ...args: unknown[]) => handlers.get(channel)!({}, ...args),
  };
}

describe('IPC bridge', () => {
  let dir: string;
  beforeEach(() => {
    dir = makeTempDir();
    vi.spyOn(console, 'log').mockImplementation(() => {});
    vi.spyOn(Math, 'random').mockReturnValue(0);
  });
  afterEach(() => {
    vi.restoreAllMocks();
    fs.rmSync(dir, { recursive: true, force: true });
  });

  it('preload exposes feedback.submit/list on window.knowledgeBase via the feedback channels', async () => {
    await import('../src/preload/preload');
    const kb = exposed.knowledgeBase;
    expect(typeof kb.feedback.submit).toBe('function');
    expect(typeof kb.feedback.list).toBe('function');

    kb.feedback.submit('abc', 'up');
    expect(invoke).toHaveBeenLastCalledWith(IPC_CHANNELS.SUBMIT_FEEDBACK, 'abc', 'up');
    kb.feedback.list();
    expect(invoke).toHaveBeenLastCalledWith(IPC_CHANNELS.LIST_FEEDBACK);
  });

  it('main handles the feedback channels end to end', async () => {
    const ipc = fakeIpcMain();
    registerIpcHandlers(ipc as never, makeServices(dir));
    const answer = await ipc.call(IPC_CHANNELS.ASK_QUESTION, 'how is logging done?');
    await ipc.call(IPC_CHANNELS.SUBMIT_FEEDBACK, answer.id, 'down');
    expect(await ipc.call(IPC_CHANNELS.LIST_FEEDBACK)).toEqual([
      expect.objectContaining({ answerId: answer.id, rating: 'down' }),
    ]);
  });
});
EOF
