import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import * as fs from 'fs';
import * as path from 'path';
import { IPC_CHANNELS } from '../src/shared/types';
import { registerIpcHandlers } from '../src/main/ipc-handlers';
import { makeServices, makeTempDir, SAMPLES_DIR } from './helpers';

function fakeIpcMain() {
  const handlers = new Map<string, (...args: any[]) => any>();
  return {
    handle: (channel: string, fn: (...args: any[]) => any) => handlers.set(channel, fn),
    call: (channel: string, ...args: unknown[]) => handlers.get(channel)!({}, ...args),
  };
}

/** Import all samples, index them, ask and rate: every store has data. */
async function populate(s: ReturnType<typeof makeServices>) {
  const docs = fs.readdirSync(SAMPLES_DIR).map(f => s.documentService.importDocument(path.join(SAMPLES_DIR, f)));
  await s.indexingService.startIndexing();
  const a = await s.qaService.ask('What does the retrieval plan say?');
  s.qaService.submitFeedback(a.id, 'up');
  return docs;
}

describe('reset all data', () => {
  let dir: string;
  beforeEach(() => {
    dir = makeTempDir();
    vi.spyOn(console, 'log').mockImplementation(() => {});
    vi.spyOn(console, 'warn').mockImplementation(() => {});
    vi.spyOn(Math, 'random').mockReturnValue(0);
  });
  afterEach(() => {
    vi.restoreAllMocks();
    fs.rmSync(dir, { recursive: true, force: true });
  });

  it('app:reset clears documents, chunks, index, Q&A history and feedback', async () => {
    const s = makeServices(dir);
    const docs = await populate(s);
    expect(s.indexingService.getAllChunks().length).toBeGreaterThan(0);
    expect(s.qaService.getHistory()).toHaveLength(1);
    expect(s.qaService.getFeedback()).toHaveLength(1);

    const ipc = fakeIpcMain();
    registerIpcHandlers(ipc as never, s);
    await ipc.call(IPC_CHANNELS.RESET_DATA);

    expect(s.documentService.listDocuments()).toEqual([]);
    expect(s.indexingService.getAllChunks()).toEqual([]);
    for (const d of docs) expect(s.indexingService.getChunksForDocument(d.id)).toEqual([]);
    expect(s.qaService.getHistory()).toEqual([]);
    expect(s.qaService.getFeedback()).toEqual([]);
    expect(s.indexingService.getStatus()).toMatchObject({ indexStatus: 'idle', documentsLoaded: 0, indexedCount: 0 });
    // Nothing left on disk but the empty skeleton.
    expect(fs.readdirSync(dir).sort()).toEqual(['documents', 'index']);
    expect(fs.readdirSync(path.join(dir, 'documents'))).toEqual([]);
  });

  it('the empty state persists after a restart and the app is usable again', async () => {
    const s = makeServices(dir);
    await populate(s);
    s.persistence.resetAll();

    const restarted = makeServices(dir);
    expect(restarted.documentService.listDocuments()).toEqual([]);
    expect(restarted.qaService.getHistory()).toEqual([]);
    expect(restarted.qaService.getFeedback()).toEqual([]);
    expect(restarted.indexingService.getAllChunks()).toEqual([]);

    const doc = restarted.documentService.importDocument(path.join(SAMPLES_DIR, 'design-notes.md'));
    await restarted.indexingService.startIndexing(doc.id);
    expect(restarted.indexingService.getAllChunks().length).toBeGreaterThan(0);
  });
});
EOF
