    $('header button:last-child').click(); // Refresh, so the sidebar shows the imports
    await waitFor(() => document.body.innerText.includes('Documents (3)'), 'sidebar to list 3 documents');
    const docs = await window.knowledgeBase.documents.list();
    assert(docs.length === 3 && docs.every(d => d.status === 'indexed'), '3 indexed documents');
    assert((await window.knowledgeBase.feedback.list()).length === 1, 'one rating');
    return { documents: docs.length, history: (await window.knowledgeBase.qa.history()).length };
  `,
  'reset-ui-asks-then-cancel': `
    $('button[aria-label="Reset all data"]').click();
    const dialog = await waitFor(() => $('[role="alertdialog"]'), 'confirmation prompt');
    assert(dialog.innerText.includes('Delete all documents'), 'prompt explains what is deleted');
    assert((await window.knowledgeBase.documents.list()).length === 3, 'nothing deleted before confirming');
    Array.from(dialog.querySelectorAll('button')).find(b => b.innerText === 'Cancel').click();
    await waitFor(() => !$('[role="alertdialog"]') && $('button[aria-label="Reset all data"]'), 'prompt to close');
    assert((await window.knowledgeBase.documents.list()).length === 3, 'cancel keeps the data');
    return { prompt: dialog.innerText, documentsAfterCancel: 3 };
  `,
  'reset-via-api': `
    await window.knowledgeBase.app.reset();
    const state = {
      documents: await window.knowledgeBase.documents.list(),
      history: await window.knowledgeBase.qa.history(),
      feedback: await window.knowledgeBase.feedback.list(),
      status: await window.knowledgeBase.indexing.status(),
    };
    assert(state.documents.length === 0 && state.history.length === 0 && state.feedback.length === 0, 'all empty after reset');
    return state;
  `,
  'reset-still-empty': `
    const state = {
      documents: await window.knowledgeBase.documents.list(),
      history: await window.knowledgeBase.qa.history(),
      feedback: await window.knowledgeBase.feedback.list(),
    };
    assert(state.documents.length === 0 && state.history.length === 0 && state.feedback.length === 0, 'still empty after restart');
    assert(document.body.innerText.includes('Documents (0)'), 'sidebar shows no documents');
    return state;
  `,
  'reset-ui-confirm': `
    $('button[aria-label="Reset all data"]').click();
    const dialog = await waitFor(() => $('[role="alertdialog"]'), 'confirmation prompt');
    Array.from(dialog.querySelectorAll('button')).find(b => b.innerText.startsWith('Yes')).click();
    await waitFor(async () => (await window.knowledgeBase.documents.list()).length === 0, 'reset to finish');
    await waitFor(() => document.body.innerText.includes('Documents (0)'), 'UI to show the empty state');
    assert((await window.knowledgeBase.qa.history()).length === 0, 'history empty');
    assert((await window.knowledgeBase.feedback.list()).length === 0, 'feedback empty');
    return { uiReset: true };
  `,
};
'''
open(p,'w').write(s)

p='scripts/verify-app.sh'
s=open(p).read()
s=s.replace('''FEATURES=("${@:-answer-feedback}")''','''feature_reset_all_data() {
  local d; d=$(mktemp -d -t kb-verify-reset)
  echo "-- reset-all-data (data: $d)"
  run "$d" reset-seed reset-ui-asks-then-cancel reset-via-api
  echo "   [restart]"
  run "$d" reset-still-empty
  echo "   [restart] UI path: seed, confirm in the UI"
  run "$d" reset-seed reset-ui-confirm
  echo "   [restart]"
  run "$d" reset-still-empty
}

ALL=(answer-feedback reset-all-data)
if [[ $# -gt 0 ]]; then FEATURES=("$@"); else FEATURES=("${ALL[@]}"); fi''')
s=s.replace('''for f in "${FEATURES[@]}"; do''','''for f in "${FEATURES[@]}"; do''')
open(p,'w').write(s)
