  /** Question waiting for an answer, shown as the last user bubble. */
  pendingQuestion?: string | null;
  error?: string | null;
}

const userBubble = {
  alignSelf: 'flex-end',
  maxWidth: '75%',
  padding: '8px 12px',
  background: '#533483',
  color: '#fff',
  borderRadius: '12px 12px 2px 12px',
  fontSize: '14px',
  lineHeight: 1.5,
  whiteSpace: 'pre-wrap' as const,
};

const assistantBubble = {
  alignSelf: 'flex-start',
  maxWidth: '85%',
  padding: '10px 14px',
  background: '#1a1a3e',
  border: '1px solid #0f3460',
  borderRadius: '12px 12px 12px 2px',
  fontSize: '14px',
  lineHeight: 1.6,
};

function CitationItem({ citation }: { citation: Citation }) {
  return (
    <details data-testid="citation" style={{ marginTop: '4px', paddingLeft: '8px', borderLeft: '2px solid #533483' }}>
      <summary style={{ cursor: 'pointer', color: '#a0a0d0' }}>
        {citation.documentTitle} · chunk {citation.chunkIndex}
      </summary>
      <blockquote
        data-testid="citation-excerpt"
        style={{ margin: '6px 0 4px', padding: '6px 8px', background: '#12122a', borderRadius: '4px', color: '#c8c8e0', whiteSpace: 'pre-wrap' }}
      >
        {citation.excerpt}
      </blockquote>
    </details>
  );
}

/** The full Q&A history as a chat: question bubbles right, answers left with citations, confidence and rating. */
export function ConversationHistory({ history, ratings, onRate, pendingQuestion, error }: Props) {
  if (history.length === 0 && !pendingQuestion && !error) {
    return (
      <div style={{ color: '#666', textAlign: 'center', paddingTop: '40px' }}>
        No conversation yet. Ask a question about your documents to get started.
      </div>
    );
  }

  return (
    <ol aria-label="Conversation" style={{ listStyle: 'none', display: 'flex', flexDirection: 'column', gap: '14px' }}>
      {history.map((item, index) => (
        <li
          key={item.response.id ?? index}
          data-testid="exchange"
          data-answer-id={item.response.id}
          style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}
        >
          <div style={userBubble}>{item.question}</div>
          <div style={assistantBubble}>
            <div>{item.response.answer}</div>
            {item.response.citations.length > 0 ? (
              <div style={{ marginTop: '10px', fontSize: '12px' }}>
                <div style={{ color: '#8888bb', fontWeight: 600 }}>
                  Citations ({item.response.citations.length})
                </div>
                {item.response.citations.map((c, i) => (
                  <CitationItem key={i} citation={c} />
                ))}
              </div>
            ) : (
              <div style={{ marginTop: '8px', fontSize: '12px', color: '#777' }}>No citations</div>
            )}
            <div style={{ marginTop: '10px', fontSize: '11px', color: '#888', display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: '12px' }}>
              <ConfidenceIndicator confidence={item.response.confidence} />
              <FeedbackButtons answerId={item.response.id} rating={ratings[item.response.id]} onRate={onRate} />
              <time dateTime={item.response.timestamp} style={{ color: '#555' }}>
                {new Date(item.response.timestamp).toLocaleString()}
              </time>
            </div>
          </div>
        </li>
      ))}
      {pendingQuestion && (
        <li data-testid="pending-exchange" style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
          <div style={userBubble}>{pendingQuestion}</div>
          <div style={{ ...assistantBubble, color: '#888' }} aria-live="polite">Thinking…</div>
        </li>
      )}
      {error && (
        <li role="alert" style={{ ...assistantBubble, borderColor: '#d9534f', color: '#f2b8b5' }}>
          {error}
        </li>
      )}
    </ol>
  );
}
