import React, { useEffect, useRef, useState } from 'react';
import { FeedbackRating, QAHistory } from '../../shared/types';
import { ConversationHistory } from './ConversationHistory';

interface Props {
  history: QAHistory[];
  ratings: Record<string, FeedbackRating>;
  pendingQuestion: string | null;
  error: string | null;
  onAsk: (question: string) => void;
  onRate: (answerId: string, rating: FeedbackRating) => void;
  onClearHistory: () => void;
}

/** Question panel: the whole conversation, then the ask box. */
export function QuestionPanel({ history, ratings, pendingQuestion, error, onAsk, onRate, onClearHistory }: Props) {
  const [question, setQuestion] = useState('');
  const scrollRef = useRef<HTMLDivElement>(null);

  // Keep the newest exchange in view.
  useEffect(() => {
    const el = scrollRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [history.length, pendingQuestion, error]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!question.trim() || pendingQuestion) return;
    onAsk(question.trim());
    setQuestion('');
  };

  return (
    <section aria-label="Questions" style={{ flex: 1, display: 'flex', flexDirection: 'column', minHeight: 0 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '10px 20px', borderBottom: '1px solid #0f3460' }}>
        <h3 style={{ fontSize: '14px', fontWeight: 600, color: '#a0a0c0' }}>Conversation ({history.length})</h3>
        {history.length > 0 && (
          <button
            type="button"
            onClick={onClearHistory}
            style={{ padding: '3px 10px', background: 'transparent', color: '#d9534f', border: '1px solid #d9534f', borderRadius: '3px', cursor: 'pointer', fontSize: '12px' }}
          >
            Clear history
          </button>
        )}
      </div>
      <div ref={scrollRef} style={{ flex: 1, overflow: 'auto', padding: '16px 20px' }}>
        <ConversationHistory history={history} ratings={ratings} onRate={onRate} pendingQuestion={pendingQuestion} error={error} />
      </div>
      <form
        onSubmit={handleSubmit}
        style={{
          display: 'flex',
          padding: '12px 20px',
          borderTop: '1px solid #0f3460',
          background: '#16213e',
        }}
      >
        <input
          type="text"
          value={question}
          onChange={e => setQuestion(e.target.value)}
          placeholder="Ask a question about your documents..."
          aria-label="Question"
          style={{
            flex: 1,
            padding: '10px 14px',
            background: '#1a1a2e',
            color: '#e0e0e0',
            border: '1px solid #0f3460',
            borderRadius: '6px',
            fontSize: '14px',
            outline: 'none',
          }}
        />
        <button
          type="submit"
          disabled={!!pendingQuestion}
          style={{
            marginLeft: '10px',
            padding: '10px 20px',
            background: '#533483',
            color: '#fff',
            border: 'none',
            borderRadius: '6px',
            cursor: pendingQuestion ? 'wait' : 'pointer',
            fontSize: '14px',
            fontWeight: 500,
            opacity: pendingQuestion ? 0.6 : 1,
          }}
        >
          Ask
        </button>
      </form>
    </section>
  );
}
EOF
