  const [ratings, setRatings] = useState<Record<string, FeedbackRating>>({});
  const [confirmingReset, setConfirmingReset] = useState(false);
  const [resetting, setResetting] = useState(false);

  const refreshFeedback = useCallback(async () => {
    try {
      const entries = await window.knowledgeBase.feedback.list();
      setRatings(Object.fromEntries(entries.map(e => [e.answerId, e.rating])));
    } catch (err) {
      console.error('Failed to load feedback:', err);
    }
  }, []);

  const refreshHistory = useCallback(async () => {
    try {
      setHistory(await window.knowledgeBase.qa.history());
    } catch (err) {
      console.error('Failed to load history:', err);
    }
  }, []);

  const refreshDocuments = useCallback(async () => {
    try {
      const docs = await window.knowledgeBase.documents.list();
      setDocuments(docs);
      setSelectedDoc(prev => (prev ? docs.find(d => d.id === prev.id) ?? null : null));
      const status = await window.knowledgeBase.indexing.status();
      setAppStatus(status);
    } catch (err) {
      console.error('Failed to refresh documents:', err);
    }
  }, []);

  useEffect(() => {
    refreshDocuments();
    refreshHistory();
    refreshFeedback();
  }, [refreshDocuments, refreshHistory, refreshFeedback]);

  const handleRate = useCallback(async (answerId: string, rating: FeedbackRating) => {
    try {
      await window.knowledgeBase.feedback.submit(answerId, rating);
      setRatings(prev => ({ ...prev, [answerId]: rating }));
    } catch (err) {
      console.error('Feedback failed:', err);
    }
  }, []);

  const handleImport = useCallback(async (filePaths: string[]) => {
    for (const filePath of filePaths) {
      try {
        await window.knowledgeBase.documents.import(filePath);
      } catch (err) {
        console.error('Import failed:', filePath, err);
      }
    }
    await refreshDocuments();
  }, [refreshDocuments]);

  const handleReset = useCallback(async () => {
    setResetting(true);
    try {
      await window.knowledgeBase.app.reset();
      setSelectedDoc(null);
      setHistory([]);
      setRatings({});
      setAskError(null);
      setConfirmingReset(false);
      await refreshDocuments();
      await refreshHistory();
      await refreshFeedback();
    } catch (err) {
      console.error('Reset failed:', err);
    } finally {
      setResetting(false);
    }
  }, [refreshDocuments, refreshHistory, refreshFeedback]);

  const handleClearHistory = useCallback(async () => {
    try {
      await window.knowledgeBase.qa.clearHistory();
      setHistory([]);
