import { useState, useCallback, useEffect } from 'react';
import { DocumentList } from './components/DocumentList';
import { QuestionPanel } from './components/QuestionPanel';
import { DocumentDetail } from './components/DocumentDetail';
import { ConversationHistory } from './components/ConversationHistory';
import { StatusBar } from './components/StatusBar';
import { ImportPanel } from './components/ImportPanel';
import { FeedbackButtons } from './components/FeedbackButtons';
import { ResetControl } from './components/ResetControl';
import { Document, AppStatus, QAResponse, FeedbackRating } from '../shared/types';

export function App() {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [selectedDoc, setSelectedDoc] = useState<Document | null>(null);
  const [appStatus, setAppStatus] = useState<AppStatus>({
    documentsLoaded: 0,
    indexStatus: 'idle',
    indexedCount: 0,
    lastActivity: '',
  });
  const [lastResponse, setLastResponse] = useState<QAResponse | null>(null);
  const [showHistory, setShowHistory] = useState(false);
  const [ratings, setRatings] = useState<Record<string, FeedbackRating>>({});
  const [confirmingReset, setConfirmingReset] = useState(false);
  const [resetting, setResetting] = useState(false);

  const refreshFeedback = useCallback(async () => {
    try {
      const entries = await window.knowledgeBase.feedback.list();
      setRatings(Object.fromEntries(entries.map(e => [e.answerId, e.rating])));
    } catch (err) {
      console.error('Failed to load feedback:', err);
    }
  }, []);

  const handleRate = useCallback(async (answerId: string, rating: FeedbackRating) => {
    try {
      await window.knowledgeBase.feedback.submit(answerId, rating);
      setRatings(prev => ({ ...prev, [answerId]: rating }));
    } catch (err) {
      console.error('Feedback failed:', err);
    }
  }, []);

  const refreshDocuments = useCallback(async () => {
    try {
      const docs = await window.knowledgeBase.documents.list();
      setDocuments(docs);
      setSelectedDoc(prev => (prev ? docs.find(d => d.id === prev.id) ?? null : null));
      const status = await window.knowledgeBase.indexing.status();
      setAppStatus(status);
    } catch (err) {
      console.error('Failed to refresh documents:', err);
    }
  }, []);

  useEffect(() => {
    refreshDocuments();
    refreshFeedback();
  }, [refreshDocuments, refreshFeedback]);

  const handleImport = useCallback(async (filePaths: string[]) => {
    for (const filePath of filePaths) {
      try {
        await window.knowledgeBase.documents.import(filePath);
      } catch (err) {
        console.error('Import failed:', filePath, err);
      }
    }
    await refreshDocuments();
  }, [refreshDocuments]);

  const handleReset = useCallback(async () => {
    setResetting(true);
    try {
      await window.knowledgeBase.app.reset();
      setSelectedDoc(null);
      setLastResponse(null);
      setRatings({});
      setConfirmingReset(false);
      await refreshDocuments();
      await refreshFeedback();
    } catch (err) {
      console.error('Reset failed:', err);
    } finally {
      setResetting(false);
    }
  }, [refreshDocuments, refreshFeedback]);

  const handleSelectDocument = useCallback((doc: Document) => {
    setSelectedDoc(doc);
  }, []);

  const handleAskQuestion = useCallback(async (question: string) => {
    try {
      const response = await window.knowledgeBase.qa.ask(question);
      setLastResponse(response);
      // Refresh status after Q&A
      const status = await window.knowledgeBase.indexing.status();
      setAppStatus(status);
    } catch (err) {
      console.error('Q&A failed:', err);
    }
  }, []);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
      <header style={{
        padding: '12px 20px',
        background: '#16213e',
        borderBottom: '1px solid #0f3460',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
      }}>
        <h1 style={{ fontSize: '18px', fontWeight: 600 }}>Knowledge Base</h1>
        <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
          <ResetControl
            confirming={confirmingReset}
            busy={resetting}
            onRequest={() => setConfirmingReset(true)}
            onConfirm={handleReset}
            onCancel={() => setConfirmingReset(false)}
          />
          <button
            onClick={() => setShowHistory(!showHistory)}
            style={{
              padding: '6px 14px',
              background: showHistory ? '#533483' : '#0f3460',
              color: '#e0e0e0',
              border: '1px solid #1a1a4e',
              borderRadius: '4px',
              cursor: 'pointer',
              fontSize: '13px',
            }}
          >
            {showHistory ? 'Hide' : 'Show'} History
          </button>
          <button
            onClick={refreshDocuments}
            style={{
              padding: '6px 14px',
              background: '#0f3460',
              color: '#e0e0e0',
              border: '1px solid #1a1a4e',
              borderRadius: '4px',
              cursor: 'pointer',
              fontSize: '13px',
            }}
          >
            Refresh
          </button>
        </div>
      </header>

      <div style={{ display: 'flex', flex: 1, overflow: 'hidden' }}>
        {/* Left panel: Document list */}
        <div style={{
          width: '280px',
          borderRight: '1px solid #0f3460',
          display: 'flex',
          flexDirection: 'column',
          background: '#16213e',
        }}>
          <div style={{
            padding: '10px 16px',
            borderBottom: '1px solid #0f3460',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
          }}>
            <span style={{ fontSize: '13px', fontWeight: 500, color: '#a0a0c0' }}>
              Documents ({documents.length})
            </span>
            <ImportPanel onImport={handleImport} />
          </div>
          <DocumentList
            documents={documents}
            onSelect={handleSelectDocument}
            selectedId={selectedDoc?.id ?? null}
          />
        </div>

        {/* Right panel: Document detail + Q&A + History */}
        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
          <div style={{ flex: 1, overflow: 'auto', padding: '20px' }}>
            {showHistory ? (
              <ConversationHistory />
            ) : (
              <>
                {selectedDoc ? (
                  <DocumentDetail document={selectedDoc} onIndexed={refreshDocuments} />
                ) : (
                  <div style={{ color: '#666', textAlign: 'center', paddingTop: '40px' }}>
                    Select a document or ask a question to get started
                  </div>
                )}
                {lastResponse && (
                  <div style={{
                    marginTop: '16px',
                    padding: '16px',
                    background: '#1a1a3e',
                    borderRadius: '6px',
                    border: '1px solid #0f3460',
                  }}>
                    <div style={{ fontSize: '14px', lineHeight: 1.6 }}>{lastResponse.answer}</div>
                    {lastResponse.citations.length > 0 && (
                      <div style={{ marginTop: '10px', fontSize: '12px', color: '#8888bb' }}>
                        <strong>Citations:</strong>
                        {lastResponse.citations.map((c, i) => (
                          <div key={i} style={{ marginTop: '4px', paddingLeft: '8px', borderLeft: '2px solid #533483' }}>
                            {c.documentTitle} (chunk {c.chunkIndex}): {c.excerpt.substring(0, 100)}...
                          </div>
                        ))}
                      </div>
                    )}
                    <div style={{ marginTop: '8px', fontSize: '11px', color: '#666', display: 'flex', alignItems: 'center', gap: '12px' }}>
                      <span>Confidence: {(lastResponse.confidence * 100).toFixed(0)}%</span>
                      <FeedbackButtons answerId={lastResponse.id} rating={ratings[lastResponse.id]} onRate={handleRate} />
                    </div>
                  </div>
                )}
              </>
            )}
          </div>

          <QuestionPanel onAsk={handleAskQuestion} />
        </div>
      </div>

      <StatusBar status={appStatus} />
    </div>
  );
}

