import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import * as fs from 'fs';
import * as path from 'path';
import { renderToStaticMarkup } from 'react-dom/server';
import { ConversationHistory } from '../src/renderer/components/ConversationHistory';
import { confidenceLevel } from '../src/renderer/components/ConfidenceIndicator';
import { QAHistory } from '../src/shared/types';
import { makeServices, makeTempDir, SAMPLES_DIR } from './helpers';

const history: QAHistory[] = [
  {
    question: 'What is the architecture?',
    response: {
      id: 'a1',
      answer: 'A layered architecture.',
      citations: [
        { documentId: 'd1', documentTitle: 'design-notes', chunkIndex: 0, excerpt: 'The system uses layers' },
        { documentId: 'd2', documentTitle: 'retrieval-plan', chunkIndex: 2, excerpt: 'Retrieval ranks chunks' },
      ],
      confidence: 0.85,
      timestamp: '2026-11-15T10:00:00.000Z',
    },
  },
  {
    question: 'Who won the match?',
    response: { id: 'a2', answer: 'No relevant documents.', citations: [], confidence: 0.3, timestamp: '2026-11-15T10:01:00.000Z' },
  },
];

const render = (props: Partial<Parameters<typeof ConversationHistory>[0]> = {}) =>
  renderToStaticMarkup(<ConversationHistory history={history} ratings={{ a1: 'up' }} onRate={() => {}} {...props} />);

describe('ConversationHistory', () => {
  it('renders every exchange in order: question then answer', () => {
    const html = render();
    const order = ['What is the architecture?', 'A layered architecture.', 'Who won the match?', 'No relevant documents.'].map(t => html.indexOf(t));
    expect(order.every(i => i >= 0)).toBe(true);
    expect([...order].sort((a, b) => a - b)).toEqual(order);
    expect(html.match(/data-testid="exchange"/g)).toHaveLength(2);
  });

  it('shows each citation as an expandable <details> whose body is the excerpt', () => {
    const html = render();
    const citations = html.match(/<details data-testid="citation"[\s\S]*?<\/details>/g) ?? [];
    expect(citations).toHaveLength(2);
    expect(citations[0]).toMatch(/<summary[^>]*>design-notes · chunk 0<\/summary>/);
    expect(citations[0]).toMatch(/data-testid="citation-excerpt"[^>]*>The system uses layers</);
    expect(citations[0]).not.toContain(' open'); // collapsed until the user expands it
    expect(html).toContain('No citations');
  });

  it('shows a confidence indicator and feedback buttons on every answer', () => {
    const html = render();
    expect(html).toContain('aria-label="Confidence: High (85%)"');
    expect(html).toContain('aria-label="Confidence: Low (30%)"');
    expect(html.match(/aria-label="Mark answer helpful"/g)).toHaveLength(2);
    expect(html.match(/aria-label="Mark answer not helpful"/g)).toHaveLength(2);
    expect(html).toMatch(/aria-label="Mark answer helpful" aria-pressed="true"/); // a1 is rated up
  });

  it('shows the pending question and the empty state', () => {
    expect(render({ pendingQuestion: 'Still thinking?' })).toMatch(/Still thinking\?[\s\S]*Thinking…/);
    expect(render({ history: [] })).toContain('No conversation yet');
  });

  it('maps confidence to levels', () => {
    expect(confidenceLevel(0.85).label).toBe('High');
    expect(confidenceLevel(0.5).label).toBe('Medium');
    expect(confidenceLevel(0.3).label).toBe('Low');
  });
});

describe('Q&A history persistence', () => {
  let dir: string;
  beforeEach(() => {
    dir = makeTempDir();
    vi.spyOn(console, 'log').mockImplementation(() => {});
    vi.spyOn(Math, 'random').mockReturnValue(0);
  });
  afterEach(() => {
    vi.restoreAllMocks();
    fs.rmSync(dir, { recursive: true, force: true });
  });

  it('keeps every exchange with citations and confidence across a restart', async () => {
    const s = makeServices(dir);
    s.documentService.importDocument(path.join(SAMPLES_DIR, 'retrieval-plan.md'));
    await s.indexingService.startIndexing();
    const a = await s.qaService.ask('How does retrieval ranking work?');
    const b = await s.qaService.ask('What is the weather today?');

    const h = makeServices(dir).qaService.getHistory();
    expect(h.map(x => x.question)).toEqual(['How does retrieval ranking work?', 'What is the weather today?']);
    expect(h[0].response).toEqual(a);
    expect(h[1].response).toEqual(b);
    expect(h[0].response.citations.length).toBeGreaterThan(0);
    expect(h[0].response.citations[0].excerpt.length).toBeGreaterThan(0);
  });
});
