    const out = [];
    for (let i = 0; i < 2; i++) {
      const ex = exchanges[i];
      assert(ex.innerText.includes(questions[i]), 'exchange ' + i + ' shows its question');
      const conf = ex.querySelector('[data-testid="confidence-indicator"]');
      assert(conf, 'exchange ' + i + ' has a confidence indicator');
      const citations = Array.from(ex.querySelectorAll('details[data-testid="citation"]'));
      assert(citations.length > 0, 'exchange ' + i + ' has citations');
      const c = citations[0];
      const excerpt = c.querySelector('[data-testid="citation-excerpt"]');
      assert(!c.open && excerpt.offsetHeight === 0, 'citation starts collapsed');
      c.querySelector('summary').click();
      await waitFor(() => c.open && excerpt.offsetHeight > 0, 'citation to expand');
      assert(excerpt.innerText.trim().length > 0, 'expanded citation shows an excerpt');
      assert(ex.querySelector('button[aria-label="Mark answer helpful"]') && ex.querySelector('button[aria-label="Mark answer not helpful"]'), 'feedback buttons on exchange ' + i);
      out.push({ question: questions[i], confidence: conf.getAttribute('aria-label'), citations: citations.length, excerpt: excerpt.innerText.slice(0, 60) });
    }
    return out;
  `,
};
'''
