/** Renderer-side verification steps for driver.js. Helpers come from the driver's PRELUDE. */
module.exports = {
  // ---- answer-feedback ----
  'feedback-seed': `
    const doc = await window.knowledgeBase.documents.import(SAMPLES + '/design-notes.md');
    await window.knowledgeBase.indexing.start(doc.id);

    const first = await askViaUi('What architecture pattern does the design use?');
    assert(typeof first.response.id === 'string' && first.response.id.length > 0, 'answer has a string id');
    const up = await waitFor(() => $('button[aria-label="Mark answer helpful"]'), 'helpful button');
    const down = $('button[aria-label="Mark answer not helpful"]');
    assert(down, 'not-helpful button renders');
    up.click();
    await waitFor(async () => (await window.knowledgeBase.feedback.list()).some(f => f.answerId === first.response.id && f.rating === 'up'), 'UI rating stored');
    await waitFor(() => up.getAttribute('aria-pressed') === 'true', 'helpful button pressed');

    const second = await window.knowledgeBase.qa.ask('How is retrieval done?');
    assert(second.id && second.id !== first.response.id, 'second answer has a different id');
    await window.knowledgeBase.feedback.submit(second.id, 'down');
    const list = await window.knowledgeBase.feedback.list();
    assert(list.length === 2, 'two ratings stored, got ' + list.length);
    return { ids: [first.response.id, second.id], list };
  `,
  'feedback-after-restart': `
    const list = await window.knowledgeBase.feedback.list();
    const ids = (await window.knowledgeBase.qa.history()).map(h => h.response.id);
    assert(list.length === 2, 'ratings survived restart, got ' + list.length);
    assert(list[0].answerId === ids[0] && list[0].rating === 'up', 'first rating is up for first answer');
    assert(list[1].answerId === ids[1] && list[1].rating === 'down', 'second rating is down for second answer');
    assert(list.every(f => !isNaN(Date.parse(f.timestamp))), 'timestamps are ISO dates');
    return { list };
  `,

  // ---- reset-all-data ----
  'reset-seed': `
    for (const f of ['design-notes.md', 'meeting-summary.txt', 'retrieval-plan.md']) {
      await window.knowledgeBase.documents.import(SAMPLES + '/' + f);
    }
    await window.knowledgeBase.indexing.start();
    const qa = await askViaUi('What did the meeting decide about retrieval?');
    await window.knowledgeBase.feedback.submit(qa.response.id, 'up');
    $('header button:last-child').click(); // Refresh, so the sidebar shows the imports
    await waitFor(() => document.body.innerText.includes('Documents (3)'), 'sidebar to list 3 documents');
    const docs = await window.knowledgeBase.documents.list();
    assert(docs.length === 3 && docs.every(d => d.status === 'indexed'), '3 indexed documents');
    assert((await window.knowledgeBase.feedback.list()).length === 1, 'one rating');
    return { documents: docs.length, history: (await window.knowledgeBase.qa.history()).length };
  `,
  'reset-ui-asks-then-cancel': `
    $('button[aria-label="Reset all data"]').click();
    const dialog = await waitFor(() => $('[role="alertdialog"]'), 'confirmation prompt');
    assert(dialog.innerText.includes('Delete all documents'), 'prompt explains what is deleted');
    assert((await window.knowledgeBase.documents.list()).length === 3, 'nothing deleted before confirming');
    Array.from(dialog.querySelectorAll('button')).find(b => b.innerText === 'Cancel').click();
    await waitFor(() => !$('[role="alertdialog"]') && $('button[aria-label="Reset all data"]'), 'prompt to close');
    assert((await window.knowledgeBase.documents.list()).length === 3, 'cancel keeps the data');
    return { prompt: dialog.innerText, documentsAfterCancel: 3 };
  `,
  'reset-via-api': `
    await window.knowledgeBase.app.reset();
    const state = {
      documents: await window.knowledgeBase.documents.list(),
      history: await window.knowledgeBase.qa.history(),
      feedback: await window.knowledgeBase.feedback.list(),
      status: await window.knowledgeBase.indexing.status(),
    };
    assert(state.documents.length === 0 && state.history.length === 0 && state.feedback.length === 0, 'all empty after reset');
    return state;
  `,
  'reset-still-empty': `
    const state = {
      documents: await window.knowledgeBase.documents.list(),
      history: await window.knowledgeBase.qa.history(),
      feedback: await window.knowledgeBase.feedback.list(),
    };
    assert(state.documents.length === 0 && state.history.length === 0 && state.feedback.length === 0, 'still empty after restart');
    assert(document.body.innerText.includes('Documents (0)'), 'sidebar shows no documents');
    return state;
  `,
  'reset-ui-confirm': `
    $('button[aria-label="Reset all data"]').click();
    const dialog = await waitFor(() => $('[role="alertdialog"]'), 'confirmation prompt');
    Array.from(dialog.querySelectorAll('button')).find(b => b.innerText.startsWith('Yes')).click();
    await waitFor(async () => (await window.knowledgeBase.documents.list()).length === 0, 'reset to finish');
    await waitFor(() => document.body.innerText.includes('Documents (0)'), 'UI to show the empty state');
    assert((await window.knowledgeBase.qa.history()).length === 0, 'history empty');
    assert((await window.knowledgeBase.feedback.list()).length === 0, 'feedback empty');
    return { uiReset: true };
  `,
};

