/**
 * Drives the real built app (dist/) inside Electron, for by-hand style verification.
 *
 *   env -u NODE_OPTIONS npx electron scripts/verify-app/driver.js <userDataDir> <step> [<step>...]
 *
 * Each step is renderer code from steps.js, evaluated in the app window (so it only has
 * what the page has: window.knowledgeBase and the DOM). The special step "reload"
 * reloads the window. EXTRA_STEPS=<file.js> adds ad-hoc debug steps. Running the driver again with the same userDataDir is a restart.
 * Prints "VERIFY <step> OK <json>" per step; exits 1 on the first failure.
 */
const path = require('path');
const { app, BrowserWindow } = require('electron');
const steps = Object.assign(require("./steps"), process.env.EXTRA_STEPS ? require(process.env.EXTRA_STEPS) : {});

const [userDataDir, ...stepNames] = process.argv.slice(2).filter(a => !a.startsWith('--'));
if (!userDataDir || stepNames.length === 0) {
  console.error('usage: driver.js <userDataDir> <step> [<step>...]');
  process.exit(2);
}
app.setPath('userData', path.resolve(userDataDir));

const PRELUDE = `
  const SAMPLES = ${JSON.stringify(path.resolve(__dirname, '..', '..', 'data', 'sample-documents'))};
  const $ = s => document.querySelector(s);
  const $$ = s => Array.from(document.querySelectorAll(s));
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const assert = (cond, msg) => { if (!cond) throw new Error('ASSERT: ' + msg); };
  async function waitFor(fn, what, ms = 5000) {
    const end = Date.now() + ms;
    for (;;) {
      const v = await fn();
      if (v) return v;
      if (Date.now() > end) throw new Error('Timed out waiting for ' + what);
      await sleep(50);
    }
  }
  function typeInto(input, value) {
    const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set;
    setter.call(input, value);
    input.dispatchEvent(new Event('input', { bubbles: true }));
  }
  async function askViaUi(question) {
    const before = (await window.knowledgeBase.qa.history()).length;
    typeInto($('input[placeholder^="Ask a question"]'), question);
    $('form button[type="submit"]').click();
    await waitFor(async () => (await window.knowledgeBase.qa.history()).length > before, 'answer to be stored');
    const h = await window.knowledgeBase.qa.history();
    return h[h.length - 1];
  }
`;

async function runStep(win, name) {
  if (name === 'reload') {
    await new Promise(resolve => {
      win.webContents.once('did-finish-load', resolve);
      win.webContents.reload();
    });
    return { reloaded: true };
  }
  const body = steps[name];
  if (!body) throw new Error(`Unknown step: ${name}`);
  const code = `(async () => { ${PRELUDE}\n${body}\n })()`;
  return win.webContents.executeJavaScript(code, true);
}

app.on('browser-window-created', (_e, win) => {
  win.webContents.once('did-finish-load', async () => {
    let code = 0;
    try {
      // Let React mount and the initial data load finish.
      await win.webContents.executeJavaScript(
        `new Promise(r => { const t = () => document.querySelector('header') ? setTimeout(r, 300) : setTimeout(t, 50); t(); })`
      );
      for (const name of stepNames) {
        const result = await runStep(win, name);
        console.log(`VERIFY ${name} OK ${JSON.stringify(result)}`);
      }
    } catch (err) {
      console.log(`VERIFY FAILED ${err && err.message ? err.message : err}`);
      code = 1;
    }
    app.exit(code);
  });
});

process.env.LOG_LEVEL = process.env.LOG_LEVEL || 'WARN';
require(path.resolve(__dirname, '..', '..', 'dist', 'main', 'main.js'));

