p='scripts/verify-app/steps.js'
s=open(p).read()
s=s.rstrip()
assert s.endswith('};')
s=s[:-2].rstrip()+'''

  // ---- conversation-history ----
  'conversation-seed': `
    for (const f of ['design-notes.md', 'retrieval-plan.md']) {
      await window.knowledgeBase.documents.import(SAMPLES + '/' + f);
    }
    // Index through the UI: refresh, open each document, press "Index Document".
    $$('header button').find(b => b.innerText === 'Refresh').click();
    await waitFor(() => document.body.innerText.includes('Documents (2)'), 'sidebar to list 2 documents');
    for (const title of ['design-notes', 'retrieval-plan']) {
      const item = await waitFor(() => $$('div').find(d => d.firstChild && d.firstChild.textContent === title && d.style.cursor === 'pointer'), 'sidebar item ' + title);
      item.click();
      const btn = await waitFor(() => $$('button').find(b => b.innerText === 'Index Document'), 'Index Document button');
      btn.click();
      await waitFor(() => !$$('button').some(b => b.innerText === 'Index Document'), title + ' to be indexed');
    }
    const docs = await window.knowledgeBase.documents.list();
    assert(docs.every(d => d.status === 'indexed'), 'both documents indexed via the UI');

    await askViaUi('What architecture pattern does the design use?');
    await waitFor(() => $$('[data-testid="exchange"]').length === 1, 'first exchange rendered');
    await askViaUi('How does retrieval rank chunks?');
    await waitFor(() => $$('[data-testid="exchange"]').length === 2, 'second exchange rendered');
    return { exchanges: $$('[data-testid="exchange"]').length };
  `,
  'conversation-check': `
    const exchanges = await waitFor(() => { const e = $$('[data-testid="exchange"]'); return e.length === 2 && e; }, 'two exchanges after load');
    const questions = ['What architecture pattern does the design use?', 'How does retrieval rank chunks?'];
    const out = [];
    for (let i = 0; i < 2; i++) {
      const ex = exchanges[i];
      assert(ex.innerText.includes(questions[i]), 'exchange ' + i + ' shows its question');
      const conf = ex.querySelector('[data-testid="confidence-indicator"]');
      assert(conf, 'exchange ' + i + ' has a confidence indicator');
      const citations = Array.from(ex.querySelectorAll('details[data-testid="citation"]'));
      assert(citations.length > 0, 'exchange ' + i + ' has citations');
      const c = citations[0];
      const excerpt = c.querySelector('[data-testid="citation-excerpt"]');
      assert(!c.open && excerpt.offsetHeight === 0, 'citation starts collapsed');
      c.querySelector('summary').click();
      await waitFor(() => c.open && excerpt.offsetHeight > 0, 'citation to expand');
      assert(excerpt.innerText.trim().length > 0, 'expanded citation shows an excerpt');
      assert(ex.querySelector('button[aria-label="Mark answer helpful"]') && ex.querySelector('button[aria-label="Mark answer not helpful"]'), 'feedback buttons on exchange ' + i);
      out.push({ question: questions[i], confidence: conf.getAttribute('aria-label'), citations: citations.length, excerpt: excerpt.innerText.slice(0, 60) });
    }
    return out;
  `,
};
'''
open(p,'w').write(s)

